55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const isKnownType = (item: Item): boolean => item.type in BASE_PREMIUMS;
72	
73	const basePremiumOfItem = (item: Item): number => {
74	  if (!isKnownType(item)) {
75	    throw new Error(`Unknown item type: ${item.type}`);
76	  }
77	  return BASE_PREMIUMS[item.type];
78	};
79	
80	const sumOfItemBasePremiums = (items: Item[]): number =>
81	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
82	
83	const groupByType = (items: Item[]): Item[][] =>
84	  Object.values(
85	    items.reduce<Record<string, Item[]>>(
86	      (groups, item) => ({
87	        ...groups,
88	        [item.type]: [...(groups[item.type] ?? []), item],
89	      }),
90	      {},
91	    ),
92	  );
93	
94	const basePremiumOfGroup = (items: Item[]): number =>
95	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
96	
97	const policyBasePremium = (items: Item[]): number =>
98	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
99	
100	const CURSED_SURCHARGE_RATE = 0.5;
101	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
102	
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	const isCursed = (item: Item): boolean => item.cursed === true;
106	
107	const UNENCHANTED = 0;
108	
109	const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;
110	
111	const isHighlyEnchanted = (item: Item): boolean =>
112	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
113	
114	const NO_SURCHARGE_RATE = 0;
115	
116	const surchargeRateOfItem = (item: Item): number =>
117	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
118	  (isHighlyEnchanted(item)
119	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
120	    : NO_SURCHARGE_RATE);
121	
122	const surchargeOfItem = (item: Item): number =>
123	  basePremiumOfItem(item) * surchargeRateOfItem(item);
124	
125	const sumOfItemSurcharges = (items: Item[]): number =>
126	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
127	
128	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
129	
130	const firstInsuranceSurcharge = (basePremium: number): number =>
131	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
132	
133	const roundPremiumInMHPCOsFavour = (premium: number): number =>
134	  Math.ceil(premium);
135	
136	const LOYALTY_DISCOUNT_RATE = 0.2;
137	const LOYALTY_YEARS_THRESHOLD = 2;
138	const NO_DISCOUNT = 0;
139	
140	const isLoyal = (customer: Customer): boolean =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
142	
143	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
144	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
145	
146	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
147	
148	const isFollowUpContract = (previousQuoteCount: number): boolean =>
149	  previousQuoteCount > 0;
150	
151	const followUpContractDiscount = (
152	  previousQuoteCount: number,
153	  basePremium: number,
154	): number =>
155	  isFollowUpContract(previousQuoteCount)
156	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
157	    : NO_DISCOUNT;
158	
159	const quote = (
160	  items: Item[],
161	  customer: Customer,
162	  previousQuoteCount: number,
163	): QuoteResult => {
164	  const basePremium = policyBasePremium(items);
165	  const surcharges =
166	    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
167	  const discounts =
168	    loyaltyDiscount(customer, basePremium) +
169	    followUpContractDiscount(previousQuoteCount, basePremium);
170	  return {
171	    premium: roundPremiumInMHPCOsFavour(
172	      PROCESSING_FEE + basePremium + surcharges - discounts,
173	    ),
174	  };
175	};
176	
177	const DEDUCTIBLE = 100;
178	const INSURANCE_VALUES: Record<string, number> = {
179	  sword: 1000,
180	  amulet: 600,
181	  rune: 250,
182	};
183	const CAP_FACTOR = 2;
184	
185	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
186	const HALF_REIMBURSEMENT_RATE = 0.5;
187	const FULL_REIMBURSEMENT_RATE = 1;
188	
189	const damagedItem = (damage: Damage, policyItems: Item[]): Item =>
190	  policyItems.find((item) => item.type === damage.itemType)!;
191	
192	const isDeeplyEnchanted = (item: Item): boolean =>
193	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
194	
195	const reimbursementRateOfItem = (item: Item): number =>
196	  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
197	
198	const payoutOfDamage = (damage: Damage, policyItems: Item[]): number =>
199	  damage.amount * reimbursementRateOfItem(damagedItem(damage, policyItems)) -
200	  DEDUCTIBLE;
201	
202	const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
203	  incident.damages.reduce(
204	    (sum, damage) => sum + payoutOfDamage(damage, policyItems),
205	    0,
206	  );
207	
208	const insuranceSum = (items: Item[]): number =>
209	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
210	
211	const capOfPolicy = (policyItems: Item[]): number =>
212	  CAP_FACTOR * insuranceSum(policyItems);
213	
214	const roundPayoutInMHPCOsFavour = (payout: number): number =>
215	  Math.floor(payout);
216	
217	const claim = (
218	  incident: Incident,
219	  policyItems: Item[],
220	  availableCap: number,
221	): ClaimResult => {
222	  const payout = roundPayoutInMHPCOsFavour(
223	    Math.min(payoutOfIncident(incident, policyItems), availableCap),
224	  );
225	  return {
226	    payout,
227	    remainingCap: availableCap - payout,
228	  };
229	};
230	
231	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
232	
233	const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);
234	
235	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
236	  quoteSteps(steps)[policy].items;
237	
238	const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
239	  quoteSteps(steps.slice(0, stepIndex)).length;
240	
241	type RemainingCaps = Record<number, number>;
242	
243	const availableCapOfPolicy = (
244	  remainingCaps: RemainingCaps,
245	  policyItems: Item[],
246	  policy: number,
247	): number => remainingCaps[policy] ?? capOfPolicy(policyItems);
248	
249	export const runScenario = (scenario: Scenario): ScenarioResult => {
250	  const remainingCaps: RemainingCaps = {};
251	  const results = scenario.steps.map((step, stepIndex) => {
252	    if (isQuoteStep(step)) {
253	      return quote(
254	        step.items,
255	        scenario.customer,
256	        quoteCountBefore(scenario.steps, stepIndex),
257	      );
258	    }
259	    const policyItems = insuredItemsOfPolicy(scenario.steps, step.policy);
260	    const result = claim(
261	      step.incident,
262	      policyItems,
263	      availableCapOfPolicy(remainingCaps, policyItems, step.policy),
264	    );
265	    remainingCaps[step.policy] = result.remainingCap;
266	    return result;
267	  });
268	  return { results };
269	};
